// Package catalog is PantherClaw's pinned copy of the MITRE ATT&CK
// Enterprise and MITRE ATLAS catalogs (G0 M28 D710, D711, D711a): ids,
// names, tactics, parents, platforms, flags and URLs, generated by
// `task mitre:update` from the sources pinned in tools/mitre/pins.json and
// embedded in the build. It is a pure leaf: standard library and embed only.
//
//nolint:misspell // MITRE is a proper noun (the ATT&CK and ATLAS publisher), not "miter".
package catalog

import (
	"crypto/sha256"
	_ "embed"
	"encoding/hex"
	"encoding/json/v2"
	"fmt"
	"strings"
	"sync"
)

// Format is the generated files' format id (D711).
const Format = "pantherclaw.mitre-catalog/v1"

// Framework names a catalog.
type Framework string

// The two catalogs (D710).
const (
	FrameworkATLAS  Framework = "atlas"
	FrameworkATTACK Framework = "attack-enterprise"
)

// Frameworks lists both catalogs, ATLAS first.
func Frameworks() []Framework { return []Framework{FrameworkATLAS, FrameworkATTACK} }

// Tactic is one tactic of a matrix.
type Tactic struct {
	ID        string `json:"id"`
	ShortName string `json:"short_name"`
	Name      string `json:"name"`
	Order     int    `json:"order"`
	URL       string `json:"url"`
}

// Technique is one technique or sub-technique. Tactics are tactic short
// names in the matrix's order; Parent is empty for a technique.
type Technique struct {
	ID         string   `json:"id"`
	Name       string   `json:"name"`
	Tactics    []string `json:"tactics"`
	Parent     string   `json:"parent"`
	Platforms  []string `json:"platforms"`
	Deprecated bool     `json:"deprecated"`
	Revoked    bool     `json:"revoked"`
	URL        string   `json:"url"`
}

// Catalog is one pinned catalog. Digest is the hex SHA-256 of the
// embedded file's bytes.
type Catalog struct {
	Format       string      `json:"format"`
	Framework    Framework   `json:"framework"`
	Version      string      `json:"version"`
	SourceURL    string      `json:"source_url"`
	SourceSHA256 string      `json:"source_sha256"`
	Notice       string      `json:"notice"`
	Digest       string      `json:"-"`
	Tactics      []Tactic    `json:"tactics"`
	Techniques   []Technique `json:"techniques"`

	byID    map[string]int
	tactics map[string]int
}

var (
	//go:embed attack-enterprise.json
	attackRaw []byte
	//go:embed atlas.json
	atlasRaw []byte
)

func raw(f Framework) []byte {
	switch f {
	case FrameworkATLAS:
		return atlasRaw
	case FrameworkATTACK:
		return attackRaw
	}
	panic(fmt.Sprintf("catalog: unknown framework %q", f))
}

var (
	loadATLAS  = sync.OnceValue(func() *Catalog { return mustParse(FrameworkATLAS) })
	loadATTACK = sync.OnceValue(func() *Catalog { return mustParse(FrameworkATTACK) })
)

// Load returns a framework's embedded catalog, parsed once. It panics on
// an unknown framework or a bad embed; a test proves both files load.
func Load(f Framework) *Catalog {
	switch f {
	case FrameworkATLAS:
		return loadATLAS()
	case FrameworkATTACK:
		return loadATTACK()
	}
	panic(fmt.Sprintf("catalog: unknown framework %q", f))
}

func mustParse(f Framework) *Catalog {
	b := raw(f)
	var c Catalog
	if err := json.Unmarshal(b, &c, json.RejectUnknownMembers(true)); err != nil {
		panic(fmt.Sprintf("catalog %s: %v", f, err))
	}
	if c.Format != Format || c.Framework != f {
		panic(fmt.Sprintf("catalog %s: format %q, framework %q", f, c.Format, c.Framework))
	}
	c.Digest = Digest(f)
	c.byID = make(map[string]int, len(c.Techniques))
	for i, t := range c.Techniques {
		c.byID[t.ID] = i
	}
	c.tactics = make(map[string]int, len(c.Tactics))
	for i, t := range c.Tactics {
		c.tactics[t.ShortName] = i
	}
	return &c
}

// Digest is the hex SHA-256 of a framework's embedded catalog file.
func Digest(f Framework) string {
	sum := sha256.Sum256(raw(f))
	return hex.EncodeToString(sum[:])
}

// Technique returns a technique or sub-technique by id, deprecated and
// revoked ones included.
func (c *Catalog) Technique(id string) (Technique, bool) {
	i, ok := c.byID[id]
	if !ok {
		return Technique{}, false
	}
	return c.Techniques[i], true
}

// Tactic returns a tactic by its short name.
func (c *Catalog) Tactic(shortName string) (Tactic, bool) {
	i, ok := c.tactics[shortName]
	if !ok {
		return Tactic{}, false
	}
	return c.Tactics[i], true
}

// Subtechniques returns id's sub-techniques, sorted by id, deprecated and
// revoked ones included.
func (c *Catalog) Subtechniques(id string) []Technique {
	var out []Technique
	for _, t := range c.Techniques {
		if t.Parent == id {
			out = append(out, t)
		}
	}
	return out
}

// Matrix returns the cells of the matrix (G0 M28 D712): techniques that are
// no sub-technique and neither deprecated nor revoked, sorted by id.
func (c *Catalog) Matrix() []Technique {
	var out []Technique
	for _, t := range c.Techniques {
		if t.Parent == "" && !t.Deprecated && !t.Revoked {
			out = append(out, t)
		}
	}
	return out
}

// Active reports whether a technique is in the catalog and neither
// deprecated nor revoked.
func (c *Catalog) Active(id string) bool {
	t, ok := c.Technique(id)
	return ok && !t.Deprecated && !t.Revoked
}

// KnownATTACK reports whether id is in the pinned ATT&CK Enterprise
// catalog. Deprecated and revoked ids count, so stored custom rules keep
// parsing (D710).
func KnownATTACK(id string) bool {
	_, ok := Load(FrameworkATTACK).Technique(id)
	return ok
}

// KnownATLAS reports whether id is in the pinned ATLAS catalog.
func KnownATLAS(id string) bool {
	_, ok := Load(FrameworkATLAS).Technique(id)
	return ok
}

// FrameworkOf names the catalog an id belongs to by its form: "AML." is
// ATLAS, "T" is ATT&CK. It does not check that the id exists.
func FrameworkOf(id string) (Framework, bool) {
	switch {
	case strings.HasPrefix(id, "AML."):
		return FrameworkATLAS, true
	case strings.HasPrefix(id, "T"):
		return FrameworkATTACK, true
	}
	return "", false
}

// Known reports whether id is in the catalog its form names.
func Known(id string) bool {
	f, ok := FrameworkOf(id)
	if !ok {
		return false
	}
	_, ok = Load(f).Technique(id)
	return ok
}
